using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class OriginalComparisonTopologyDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/OriginalComparisonTopology.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual scalar topology and original optimal budgets",
        H("Actual scalar topology and original optimal budgets"), Blocks(
            Paragraph(Text("V is an arbitrary finite dimensional real normed space, C a pointed cone, and u its original linear unit. Where stated, C is closed and generating and u is strictly positive on nonzero C. K is the entire normalized base and P its entire extreme locus. All original linear effects between zero and u are retained; the full confirming family F(p) includes u. Pure reciprocity exchanges only two pure endpoints. No mixed reciprocity, matrix specialization, weakPair, unit-width assumption or global uniform-fiber premise is used.")),
            Describe.Lean(DescribeId.Create("original-local-budget-iff"), DeclarationHandle.Create(Owner + "original_local_budget_iff"),
                H("Whole-P continuity exactly equals finite local optimal budgets"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Under original EB3 and pure PR, Hausdorff continuity at any original pure p is equivalent to an open neighborhood U containing p in all P and a finite positive B bounding every actual chart and unit-direction extensionBudget throughout U. Forward: the exact regular-region theorem gives a neighborhood with a positive whole-diameter lower bound, and original_noncollapse_bounded_budget supplies B. Reverse: original_bounded_budget_noncollapse gives a positive diameter floor on U, placing p inside an actual closed diameter layer and hence in the whole-ball continuity set. No uniqueness or Inj hypothesis is needed."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-whole-limit-calibration"), DeclarationHandle.Create(Owner + "original_whole_limit_calibration"),
                H("Actual scale across every whole-ball limit"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For arbitrary original pure labels pn and p under EB3 and pure-only PR, Hausdorff convergence of the entire D(pn) to D(p) forces convergence of the actual common calibration coefficient. The coefficient is selected from original_common_chart_scale and obeys its all-chart, all-mixed-input law. Parameter extraction is reused from ExclusionIncidence.parameter_subsequence. Closedness of the original pure locus makes every limiting sphere point pure; sphere_extreme_injective_or_zero rules out positive rank loss, while nontriviality of the complete limiting ball excludes the zero map. The limiting affine map is therefore an actual full chart of D(p). Its fixed antipodal endpoints recover the same coefficient via (1-T(q,r))/2 and pure joint comparison continuity. No continuity of chosen charts or extra compact-pure premise is assumed."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-singleton-limit-scalars"), DeclarationHandle.Create(Owner + "original_singleton_limit_scalars"),
                H("Actual zero and infinite limits under singleton collapse"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Every whole-exclusion sequence converging to an actual singleton has calibration tending to zero and actual optimalBudget tending to positive infinity. The latter equals the original attained extensionBudget in every chart and every unit direction; optimalBudget is never accepted solely from its reciprocal definition. Diameter continuity on nonempty compact sets and the original diameter-collapse budget theorem yield divergence. This result does not assert that any collapse exists."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-scalar-subsequence"), DeclarationHandle.Create(Owner + "original_scalar_subsequence"),
                H("Both exhaustive original subsequence alternatives"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Every sequence of original pure labels tending to p has a strictly indexed subsequence on which either the whole exclusions tend to the complete D(p), with calibration and optimal budget tending to their actual values at p, or the whole exclusions tend to a pure singleton q in D(p), with calibration tending to zero and optimal budget to positive infinity. Applying the same theorem to any initial subsequence gives the complete scalar refinement. The whole-ball-or-pure-singleton dichotomy is directly reused from the frozen ReciprocalExclusionLimits owner."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-calibration-upper-semicontinuous"), DeclarationHandle.Create(Owner + "original_calibration_upperSemicontinuous"),
                H("Upper semicontinuity on all original pure labels"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("The actual common calibration is upper semicontinuous on the entire original P. For each scalar superlevel and every converging original label sequence in it, compact whole-set extraction and the exhaustive scalar alternatives force the limiting label into the same superlevel. In the singleton case the threshold is at most zero, and the actual limiting label still has strictly positive calibration. This is neither a P0 restriction nor a chosen-neighborhood statement."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-optimal-budget-lower-semicontinuous"), DeclarationHandle.Create(Owner + "original_optimalBudget_lowerSemicontinuous"),
                H("Lower semicontinuity of the actual optimum on all P"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Every scalar sublevel of the actual attained optimal budget is closed in all original P. The whole branch preserves the sublevel by scalar convergence. The singleton branch is incompatible with a finite upper bound because its actual budgets diverge. Every original individual budget remains finite and at least one; infinity is a sequence limit, not the budget assigned to an individual ball."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-discontinuity-scalar-witness"), DeclarationHandle.Create(Owner + "original_discontinuity_scalar_witness"),
                H("Every discontinuity retains its actual pure collapse and both scalar limits"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("At every actual Hausdorff discontinuity there is a sequence of original pure labels tending to p and an original pure q in D(p) such that the entire moving exclusions tend to q, their actual calibrations tend to zero and their actual optimal budgets tend to positive infinity. No collapse existence or exclusion is inferred."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-common-continuity-sets"), DeclarationHandle.Create(Owner + "original_common_continuity_sets"),
                H("Exact common continuity sets and all-P local optimal budgets"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("The original regular region R equals the continuity sets of the whole Hausdorff map D, the actual calibration a and the actual optimal budget beta. The result also gives the exact open-neighborhood local-budget equivalence in all P, uniform boundedness on every compact subset of R, positivity and the half-scale upper bound, and attained sharpness of beta in every actual chart and unit direction. At an irregular label the actual collapse witness has a tending to zero and beta to infinity, whereas a(p) is positive and beta(p) finite. The open dense R and closed nowhere-dense Sigma are provided by OriginalExclusionLimits.original_baire_regular_region. Inj and singleton full-zero confirmer hypotheses are absent here and remain confined to OriginalRowSaturation and its normal-family prerequisites."))), DescribeRole.Theorem),
            Paragraph(Text("The literal supremum over all affine face effects of their individual optimal positive-extension maxima on K agrees with the common attained budget. For each face effect the retained original_full_face_budget lift bounds its individual infimum by beta. A unit directional face effect attains beta, since every positive extension with maximum M on the compact full K is bounded by M u on C by normalization, so the directional sharp lower bound applies. Thus the supremum of the individual infima is exactly beta; it is not inferred solely from a statement about one simultaneous upper budget. The exact supremum/infimum/max-on-K formulation is checked transiently against the existing sharp theorem, with no extra named binding declaration. All results concern the original static cone, unit, full effect interval and auxiliary norm. No mixed PR, UF, CS, physical realization or novelty claim is supplied.")))));

}
